cd /tmp/vally-eval-trial-pWuczd && P=.copilot-tracking/skraft-plans/pricing && D=2026-10-06 && mkdir -p $P/features $P/details/$D $P/evidence/$D/discount tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $P/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: AC-1 to AC-3 (explicit expected values in ac.md).
  # SETTLED BUT QUERIED: AC-4 (value copied verbatim, see @needs-clarification).
  # NOT DECIDED: Platinum tier. No scenario exists on purpose; see the end of this file.

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  # Value copied verbatim from AC-4. Its title says the reduction lands "in the customer's
  # favour", yet 7 cents charged on a 7 cent subtotal means no reduction is granted.
  # Business owner must confirm the rounding rule before this is relied on (escalated to DISCUSS).
  @edge-case @needs-clarification
  Scenario: Bronze customer with a tiny basket is charged a whole number of cents
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents

  # NOT DECIDED - Platinum tier
  # The business has not agreed a reduction, so no expected value exists. No scenario, no
  # test and no placeholder is written. Add one only once the business supplies an example.
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Bronze_customer_is_charged_the_Bronze_price()
    {
        // Bronze customer is charged the Bronze price (AC-1)
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > $P/evidence/$D/discount/acceptance-red.stdout 2>&1; echo $? > $P/evidence/$D/discount/acceptance-red.exit; git rev-parse HEAD > $P/evidence/$D/discount/acceptance-red.rev; cat $P/evidence/$D/discount/acceptance-red.exit; tail -25 $P/evidence/$D/discount/acceptance-red.stdout

